-- Veranstaltung 24988 material/gallery split
-- Generated: 2026-06-24
-- Moves the former material media reference into a galerie section.
-- Material remains for downloads, links, archive objects, and dynamic references.

START TRANSACTION;

UPDATE wp_postmeta
SET meta_value = CONVERT( USING utf8mb4)
WHERE post_id = 24988
  AND meta_key = '_iss_content_json';

COMMIT;
